pub unsafe fn reset_state() {
    P_HSD_GObj = core::mem::zeroed();
    P_HSD_JObj = core::mem::zeroed();
    P_HSD_DObj = core::mem::zeroed();
    P_HSD_MObj = core::mem::zeroed();
    P_HSD_TObj = core::mem::zeroed();
    P_HSD_AObj = core::mem::zeroed();
    P_HSD_Material = core::mem::zeroed();
    P_DynamicModelDesc = core::mem::zeroed();
    P_StartMeleeRules = core::mem::zeroed();
    P_HSD_Joint = core::mem::zeroed();
    m::ifTime_data = core::mem::zeroed();
    m::ifTime_match_timer_models = core::mem::zeroed();
    super::TIMM = core::mem::zeroed();
    super::CDM = core::mem::zeroed();
    super::ARCP = core::mem::zeroed();
    super::TPOS = core::mem::zeroed();
    m::ext::HSD_GObj_JObjKind = core::mem::zeroed();
    for i in 0..4usize { fill_HSD_GObj(&mut P_HSD_GObj[i]); }
    for i in 0..12usize { fill_HSD_JObj(&mut P_HSD_JObj[i]); }
    for i in 0..3usize { fill_HSD_DObj(&mut P_HSD_DObj[i]); }
    for i in 0..3usize { fill_HSD_MObj(&mut P_HSD_MObj[i]); }
    for i in 0..3usize { fill_HSD_TObj(&mut P_HSD_TObj[i]); }
    for i in 0..3usize { fill_HSD_AObj(&mut P_HSD_AObj[i]); }
    for i in 0..3usize { fill_HSD_Material(&mut P_HSD_Material[i]); }
    for i in 0..3usize { fill_DynamicModelDesc(&mut P_DynamicModelDesc[i]); }
    for i in 0..1usize { fill_StartMeleeRules(&mut P_StartMeleeRules[i]); }
    for i in 0..4usize { fill_HSD_Joint(&mut P_HSD_Joint[i]); }
    fill_ifTime_data(&mut m::ifTime_data);
    fill_DynamicModelDesc(&mut m::ifTime_match_timer_models);
    for i in 0..4usize { super::TIMM[i] = (pick_DynamicModelDesc(1)) as _; }
    for i in 0..4usize { super::CDM[i] = (pick_DynamicModelDesc(0)) as _; }
    super::ARCP = (0) as _;
    fill_Vec3(&mut super::TPOS);
    m::ext::HSD_GObj_JObjKind = (20) as _;
}
pub unsafe fn hash_state() {
    for i in 0..4usize { hash_HSD_GObj(&P_HSD_GObj[i]); }
    for i in 0..12usize { hash_HSD_JObj(&P_HSD_JObj[i]); }
    for i in 0..3usize { hash_HSD_DObj(&P_HSD_DObj[i]); }
    for i in 0..3usize { hash_HSD_MObj(&P_HSD_MObj[i]); }
    for i in 0..3usize { hash_HSD_TObj(&P_HSD_TObj[i]); }
    for i in 0..3usize { hash_HSD_AObj(&P_HSD_AObj[i]); }
    for i in 0..3usize { hash_HSD_Material(&P_HSD_Material[i]); }
    for i in 0..3usize { hash_DynamicModelDesc(&P_DynamicModelDesc[i]); }
    for i in 0..1usize { hash_StartMeleeRules(&P_StartMeleeRules[i]); }
    for i in 0..4usize { hash_HSD_Joint(&P_HSD_Joint[i]); }
    hash_ifTime_data(&m::ifTime_data);
    hash_DynamicModelDesc(&m::ifTime_match_timer_models);
    for i in 0..4usize { hm(pi(super::TIMM[i])); }
    for i in 0..4usize { hm(pi(super::CDM[i])); }
    hm(pi(super::ARCP));
    hash_Vec3(&super::TPOS);
    hm(m::ext::HSD_GObj_JObjKind as u32);
}
